{"code": "import pandas as pd, numpy as np, statsmodels.formula.api as smf
df = pd.read_csv('data/explore.csv')
d = df.dropna(subset=['species_richness']).copy()
for e in ['canopy_cover','grazing_index','soil_moisture']:
    print("===",e)
    for r in d['region'].unique():
        dd = d[d['region']==r].dropna(subset=[e])
        m = smf.ols(f"species_richness ~ {e}", data=dd).fit()
        print(f"  {r:8s} coef={m.params[e]: .4f} p={m.pvalues[e]:.3g} n={int(m.nobs)}")
"}
